import json,os
for f in ['source.json','policy.json','coordination.json']:
 d=json.load(open(f)); print(f,os.path.getsize(f),type(d).__name__)
 if f=='source.json':
  print('keys:',list(d) if isinstance(d,dict) else '(array)')
  a=d if isinstance(d,list) else d.get('articles',[])
  for i,x in enumerate(a): print(i,x.get('number'),len(x.get('source_xml','')),len(x.get('source_notes_xml') or ''),list(x))
 else: print(json.dumps(d,ensure_ascii=False,indent=2))
